// Fused residual add + RMSNorm over contiguous bf16 rows, hidden size H in {2048, 4096, 6144, 8192}
// (GLM-5.2: 6144):
//   residual_out = bf16(x + residual)
//   normalized   = bf16((x + residual) * rsqrt(mean((x + residual)^2) + epsilon) * weight)
// One 256-thread block per row; thread t owns H/256 elements as 16-byte chunks at element
// (t % 64) * 8 + (t / 64) * H/4 + c * 512 (aiter's interleaved layout).
//
// Bit-identical by construction to aiter's add_rmsnorm_quant_kernel<bf16, bf16, 256, H/256, true,
// false, true, 1>, the HIP path of aiter.rmsnorm2d_fwd_with_add, as aiter builds it (-ffast-math,
// fp32 denormals flushed). The fp32 dataflow is read off that build's gfx950 ISA:
//   s = x + r (fp32), residual_out = RNE bf16 of s (v_cvt_pk_bf16_f32)
//   per thread: separately rounded squares, summed sequentially in element order (no fma)
//   wave: DPP quad_perm [1,0,3,2], [2,3,0,1], row_half_mirror, row_mirror, row_bcast:15,
//         row_bcast:31 (lane 63 holds the wave sum); block: (w0 + w1) + (w2 + w3)
//   r = v_rsq_f32((float)((double)(total * v_rcp_iflag_f32((float)H)) + epsilon))
//   normalized = RNE bf16 of (s * r) * (weight + 0.0f)
// What differs from aiter is only the schedule (the fast path of the GLM-5.2 candidate): no
// kernarg preload, compile-time H and strides, loads issued chunk by chunk so the sequential sum
// runs while later chunks arrive, a single ds_read_b128 for the cross-wave exchange, the last
// residual_out chunk stored in the shadow of that read, sc0|sc1 on every store, and store data
// held in its VGPRs until the end so no VALU write can race a 16-byte buffer_store.

#include <ATen/hip/HIPContext.h>
#include <hip/hip_runtime.h>
#include <torch/library.h>

#include <cstdint>
#include <initializer_list>

namespace {

using u32x4 = unsigned int __attribute__((ext_vector_type(4)));
using f32x2 = float __attribute__((ext_vector_type(2)));
using f32x4 = float __attribute__((ext_vector_type(4)));
using bf16x2 = __bf16 __attribute__((ext_vector_type(2)));

constexpr int kThreads = 256;
constexpr int kWave = 64;
constexpr int kChunkElems = 8;                   // bf16 in one 16-byte chunk
constexpr int kChunkStride = kWave * kChunkElems * 2;  // bytes between a thread's chunks
// cache-policy bits of a gfx950 buffer instruction: sc0 = 1, nt = 2, sc1 = 16
constexpr int kStreamLoad = 3;   // sc0 nt: x and residual, read once (as aiter)
constexpr int kWeightLoad = 0;   // weight: cached (as aiter)
constexpr int kResidualStore = 17;    // sc0 sc1 on both outputs (as the candidate; aiter:
constexpr int kNormalizedStore = 17;  // sc0 nt on residual_out, none on normalized)
// hwreg(HW_REG_MODE, 4, 2): the fp32 field of MODE.FP_DENORM; 0 flushes fp32 denormals in and
// out, the mode aiter's build runs in (its kernel descriptor: float_denorm_mode_32 = 0)
constexpr int kModeDenormF32 = (1 << 11) | (4 << 6) | 1;
#if defined(__gfx90a__) || defined(__gfx940__) || defined(__gfx941__) || defined(__gfx942__) || \
    defined(__gfx950__)
constexpr unsigned int kRsrcConfig = 0x00020000u;
#else
constexpr unsigned int kRsrcConfig = 0u;  // host pass only: device code is built for gfx9 CDNA
#endif

__device__ __forceinline__ __amdgpu_buffer_rsrc_t row_rsrc(const void* base, int bytes) {
    return __builtin_amdgcn_make_buffer_rsrc(const_cast<void*>(base), 0, bytes, kRsrcConfig);
}

// bf16 pair (low half first) to fp32, exactly: integer ops, as aiter
__device__ __forceinline__ f32x2 unpack(unsigned int w) {
    return f32x2{__builtin_bit_cast(float, w << 16), __builtin_bit_cast(float, w & 0xffff0000u)};
}

// fp32 pair to bf16, round to nearest even (v_cvt_pk_bf16_f32 on gfx950, as aiter)
__device__ __forceinline__ unsigned int pack(f32x2 v) {
    return __builtin_bit_cast(unsigned int, __builtin_convertvector(v, bf16x2));
}

__device__ __forceinline__ float dpp_sum(float v) {
    // every lane of a row ends with the row sum; lane 63 then holds (R3 + R2) + (R1 + R0)
    v += __builtin_bit_cast(float, __builtin_amdgcn_update_dpp(0, __builtin_bit_cast(int, v), 0xb1, 0xf, 0xf, true));
    v += __builtin_bit_cast(float, __builtin_amdgcn_update_dpp(0, __builtin_bit_cast(int, v), 0x4e, 0xf, 0xf, true));
    v += __builtin_bit_cast(float, __builtin_amdgcn_update_dpp(0, __builtin_bit_cast(int, v), 0x141, 0xf, 0xf, true));
    v += __builtin_bit_cast(float, __builtin_amdgcn_update_dpp(0, __builtin_bit_cast(int, v), 0x140, 0xf, 0xf, true));
    v += __builtin_bit_cast(float, __builtin_amdgcn_update_dpp(0, __builtin_bit_cast(int, v), 0x142, 0xf, 0xf, false));
    v += __builtin_bit_cast(float, __builtin_amdgcn_update_dpp(0, __builtin_bit_cast(int, v), 0x143, 0xf, 0xf, false));
    return v;
}

template <int kChunks>
__global__ __launch_bounds__(kThreads) void add_rmsnorm_bf16_kernel(
    const void* __restrict__ x, const void* __restrict__ residual, const void* __restrict__ weight,
    void* __restrict__ normalized, void* __restrict__ residual_out, double epsilon) {
#pragma clang fp contract(off)
    constexpr int kHidden = kThreads * kChunks * kChunkElems;
    constexpr int kRowBytes = kHidden * 2;
    __builtin_amdgcn_s_setreg(kModeDenormF32, 0);

    const int tid = static_cast<int>(threadIdx.x);
    const int lane = tid % kWave;
    const int wave = tid / kWave;
    const int voff = (lane * kChunkElems + wave * kWave * kChunks * kChunkElems) * 2;
    const int64_t row_off = static_cast<int64_t>(blockIdx.x) * kRowBytes;

    const auto x_rsrc = row_rsrc(static_cast<const char*>(x) + row_off, kRowBytes);
    const auto r_rsrc = row_rsrc(static_cast<const char*>(residual) + row_off, kRowBytes);
    const auto w_rsrc = row_rsrc(weight, kRowBytes);

    // x and residual chunk by chunk (sched_barrier: not regrouped by base), weight last: the
    // sequential sum starts on chunk 0 while later chunks are still arriving
    u32x4 xv[kChunks], rv[kChunks], wv[kChunks];
#pragma unroll
    for (int c = 0; c < kChunks; ++c) {
        xv[c] = __builtin_amdgcn_raw_buffer_load_b128(x_rsrc, voff + c * kChunkStride, 0, kStreamLoad);
        rv[c] = __builtin_amdgcn_raw_buffer_load_b128(r_rsrc, voff + c * kChunkStride, 0, kStreamLoad);
        __builtin_amdgcn_sched_barrier(0);
    }
#pragma unroll
    for (int c = 0; c < kChunks; ++c) {
        wv[c] = __builtin_amdgcn_raw_buffer_load_b128(w_rsrc, voff + c * kChunkStride, 0, kWeightLoad);
    }
    // 1 / H as the hardware rounds it (aiter: v_rcp_iflag_f32 of (float)n), in the load shadow;
    // asm keeps the compiler from folding it to the correctly rounded constant
    float inv_h;
    asm volatile("v_rcp_iflag_f32 %0, %1\n\ts_nop 0" : "=v"(inv_h) : "v"(static_cast<float>(kHidden)));

    const auto ro_rsrc = row_rsrc(static_cast<char*>(residual_out) + row_off, kRowBytes);
    f32x2 s[kChunks][4];
    u32x4 ro[kChunks];
    float sum = 0.0f;
#pragma unroll
    for (int c = 0; c < kChunks; ++c) {
#pragma unroll
        for (int j = 0; j < 4; ++j) {
            s[c][j] = unpack(xv[c][j]) + unpack(rv[c][j]);
            ro[c][j] = pack(s[c][j]);
            const f32x2 q = s[c][j] * s[c][j];
            // aiter's 0 + q0 is q0: a square is never -0
            sum = (c == 0 && j == 0) ? q[0] : sum + q[0];
            sum = sum + q[1];
        }
        if (c + 1 < kChunks) {
            __builtin_amdgcn_raw_buffer_store_b128(ro[c], ro_rsrc, voff + c * kChunkStride, 0, kResidualStore);
        }
    }

    const float wave_sum = dpp_sum(sum);
    __shared__ __attribute__((aligned(16))) float s_wave_sum[kThreads / kWave];
    if (lane == kWave - 1) {
        s_wave_sum[wave] = wave_sum;
    }
    __syncthreads();
    const f32x4 w4 = *reinterpret_cast<const f32x4*>(s_wave_sum);

    // in the shadow of that ds_read: the weights, and the last residual_out chunk
    __builtin_amdgcn_sched_barrier(0);
    // weight + 0.0f: aiter adds its (zero) gemma offset, which turns a -0 weight into +0
    f32x2 wf[kChunks][4];
#pragma unroll
    for (int c = 0; c < kChunks; ++c) {
#pragma unroll
        for (int j = 0; j < 4; ++j) {
            wf[c][j] = unpack(wv[c][j]) + f32x2{0.0f, 0.0f};
        }
    }
    __builtin_amdgcn_raw_buffer_store_b128(ro[kChunks - 1], ro_rsrc, voff + (kChunks - 1) * kChunkStride, 0, kResidualStore);
    __builtin_amdgcn_sched_barrier(0);

    // (w0 + w1) + (w2 + w3) in three scalar adds (the asm keeps it from becoming a pk_add)
    float w01 = w4[0] + w4[1];
    asm("" : "+v"(w01));
    const float total = w01 + (w4[2] + w4[3]);
    const float mean = total * inv_h;
    const float r = __builtin_amdgcn_rsqf(static_cast<float>(static_cast<double>(mean) + epsilon));
    const f32x2 r2 = {r, r};

    const auto norm_rsrc = row_rsrc(static_cast<char*>(normalized) + row_off, kRowBytes);
    u32x4 ov[kChunks];
#pragma unroll
    for (int c = 0; c < kChunks; ++c) {
#pragma unroll
        for (int j = 0; j < 4; ++j) {
            const f32x2 n = s[c][j] * r2;
            ov[c][j] = pack(n * wf[c][j]);
        }
        __builtin_amdgcn_raw_buffer_store_b128(ov[c], norm_rsrc, voff + c * kChunkStride, 0, kNormalizedStore);
    }
    // every stored chunk stays in its VGPRs to here: nothing overwrites store data in flight
#pragma unroll
    for (int c = 0; c < kChunks; ++c) {
        asm volatile("" ::"v"(ro[c]), "v"(ov[c]));
    }
}

template <int kChunks>
void launch(const at::Tensor& x, const at::Tensor& residual, const at::Tensor& weight, double epsilon,
            at::Tensor& normalized, at::Tensor& residual_out, int64_t m, hipStream_t stream) {
    add_rmsnorm_bf16_kernel<kChunks><<<dim3(static_cast<unsigned int>(m)), dim3(kThreads), 0, stream>>>(
        x.data_ptr(), residual.data_ptr(), weight.data_ptr(), normalized.data_ptr(), residual_out.data_ptr(),
        epsilon);
}

void run(const at::Tensor& x, const at::Tensor& residual, const at::Tensor& weight, double epsilon,
         at::Tensor& normalized, at::Tensor& residual_out) {
    TORCH_CHECK(x.dim() == 2, "x must be [M, H], got ", x.sizes());
    const int64_t m = x.size(0);
    const int64_t h = x.size(1);
    for (const at::Tensor* t : std::initializer_list<const at::Tensor*>{&x, &residual, &normalized, &residual_out}) {
        TORCH_CHECK(t->sizes() == x.sizes(), "x, residual, normalized, residual_out must share a shape");
    }
    TORCH_CHECK(weight.dim() == 1 && weight.size(0) == h, "weight must be [H]");
    TORCH_CHECK(h == 2048 || h == 4096 || h == 6144 || h == 8192,
                "hidden size must be 2048, 4096, 6144 or 8192, got ", h);
    for (const at::Tensor* t :
         std::initializer_list<const at::Tensor*>{&x, &residual, &weight, &normalized, &residual_out}) {
        TORCH_CHECK(t->scalar_type() == at::kBFloat16, "bf16 only, got ", t->scalar_type());
        TORCH_CHECK(t->is_contiguous(), "tensors must be contiguous");
        TORCH_CHECK(t->device() == x.device(), "tensors must share a device");
    }
    TORCH_CHECK(x.is_cuda(), "tensors must be on the GPU");
    const auto stream = at::hip::getCurrentHIPStream();
    TORCH_CHECK(stream.device_index() == x.get_device(), "tensors are not on the current device");
    TORCH_CHECK(m <= INT32_MAX, "too many rows: ", m);
    if (m == 0) {
        return;
    }
    switch (h) {
    case 2048: launch<1>(x, residual, weight, epsilon, normalized, residual_out, m, stream); break;
    case 4096: launch<2>(x, residual, weight, epsilon, normalized, residual_out, m, stream); break;
    case 6144: launch<3>(x, residual, weight, epsilon, normalized, residual_out, m, stream); break;
    case 8192: launch<4>(x, residual, weight, epsilon, normalized, residual_out, m, stream); break;
    default: break;
    }
}

}  // namespace

#define TORCH_LIBRARY_EXPAND(ns, m) TORCH_LIBRARY(ns, m)
TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, m) {
    m.def("run(Tensor x, Tensor residual, Tensor weight, float epsilon, Tensor(a!) normalized, "
          "Tensor(a!) residual_out) -> ()",
          &run);
}
